"""100 explicit policy products. Thresholds are Privi defaults, not universal standards.

Each rule: field, operator, expected value, remediation. Fields are strict typed.
"""
CATALOG = {}


def add(domain, slug, title, fields, rules, good, bad):
    name = 'privi_' + slug
    assert name not in CATALOG
    CATALOG[name] = dict(name=name, domain=domain, title='Privi ' + title,
                         fields=fields, rules=rules, example=good, failing_example=bad,
                         credit_units=2, version='1.0.0')


